style.css:
@-moz-document domain("google.com") {
/* Substituir a logo principal na página inicial */
    img[alt="Google"] {
        content: url("https://i.imgur.com/w7nyqCS.png");
        width: 300px; /* Ajuste a largura desejada */
        height: auto; /* Mantém a proporção da imagem */
    }

    /* Substituir a logo menor na barra de pesquisa */
    img[src*="logo"] {
        content: url("https://i.imgur.com/w7nyqCS.png");
        width: 100px; /* Ajuste a largura desejada */
        height: auto; /* Mantém a proporção da imagem */
    }
}
